def cal_sum(n):
    if n < 1:
        return 0  # No terms to sum for invalid or zero input

    # Initial values of the Perrin sequence
    p0, p1, p2 = 3, 0, 2
    total_sum = 0

    # Generate and sum the terms of the Perrin sequence up to the nth term
    for i in range(n):
        if i == 0:
            total_sum += p0
        elif i == 1:
            total_sum += p1
        elif i == 2:
            total_sum += p2
        else:
            next_p = p0 + p1  # Calculate next term
            total_sum += next_p  # Add it to the total sum
            p0, p1, p2 = p1, p2, next_p  # Update variables for next iteration

    return total_sum
